<script setup lang="ts">import {ref,onMounted,onUnmounted} from 'vue';import {pmsApi} from './api';const props=defineProps<{active?:boolean;permissions:string[]}>();const emit=defineEmits(['department','project','create']);const open=ref(false),expanded=ref<number[]>([]),otherOpen=ref(false),data=ref<any>({departments:[],otherProjects:[]}),error=ref('');const canCreate=()=>props.permissions.includes('*')||props.permissions.includes('project-add');async function load(){try{data.value=await pmsApi('team-space');error.value='';}catch(e){error.value=(e as Error).message;}}function toggle(id:number){expanded.value=expanded.value.includes(id)?expanded.value.filter(i=>i!==id):[...expanded.value,id];}function update(){void load();}onMounted(()=>{void load();window.addEventListener('pms:changed',update);});onUnmounted(()=>window.removeEventListener('pms:changed',update));</script><template><div class="pms-team-navigation"><button class="pms-team-toggle" :class="{active}" :aria-expanded="open" @click="open=!open"><i aria-hidden="true" class="ti ti-users"></i><span>Team Space</span><i aria-hidden="true" class="ti" :class="open?'ti-chevron-down':'ti-chevron-right'"></i></button><div v-if="open" class="pms-team-tree"><p v-if="error" class="pms-team-empty" role="alert">{{error}}</p><div v-for="department in data.departments" :key="department.id"><div class="pms-team-department"><button class="pms-team-name" @click="department.can_open_board?emit('department',department.id):toggle(department.id)"><span class="pms-tree-dot"></span><span>{{department.dept_name}}</span></button><button class="pms-team-chevron" :aria-label="'Show projects in '+department.dept_name" :aria-expanded="expanded.includes(department.id)" @click="toggle(department.id)"><i aria-hidden="true" class="ti" :class="expanded.includes(department.id)?'ti-chevron-down':'ti-chevron-right'"></i></button><button v-if="canCreate()" class="pms-team-add" :aria-label="'Create project in '+department.dept_name" @click="emit('create',department.id)"><i aria-hidden="true" class="ti ti-plus"></i></button></div><div v-if="expanded.includes(department.id)" class="pms-team-projects"><button v-for="project in department.projects" :key="project.id" @click="emit('project',project.id)"><i aria-hidden="true" class="ti ti-layout-kanban"></i><span>{{project.name}}</span><small v-if="project.approval!=='approved'" class="badge bg-label-warning">{{project.approval}}</small></button><p v-if="!department.projects.length" class="pms-team-empty">No projects yet</p></div></div><template v-if="data.otherProjects.length"><button class="pms-team-other" :aria-expanded="otherOpen" @click="otherOpen=!otherOpen"><span class="pms-tree-dot"></span><span>Other projects</span><i aria-hidden="true" class="ti" :class="otherOpen?'ti-chevron-down':'ti-chevron-right'"></i></button><div v-if="otherOpen" class="pms-team-projects"><button v-for="project in data.otherProjects" :key="project.id" @click="emit('project',project.id)"><i aria-hidden="true" class="ti ti-layout-kanban"></i><span>{{project.name}}</span></button></div></template><p v-if="!error&&!data.departments.length&&!data.otherProjects.length" class="pms-team-empty">No accessible projects yet</p></div></div></template>